from .repository import get_contacts, insert_contact, put_contact, update_contact_name

CONTACT_FIELDS = frozenset({"email", "name"})

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _validate_batch(rows):
    """Validate the complete batch up front.

    Returns a list of (normalized_email, trimmed_name) pairs in input order;
    raises ValueError on the first invalid row.
    """
    if not isinstance(rows, list):
        raise ValueError("rows must be a list of contact objects")

    normalized = []
    seen = set()
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            raise ValueError(f"row {index} must be an object with 'email' and 'name' fields")
        if set(row) != CONTACT_FIELDS:
            raise ValueError(f"row {index} must contain exactly the fields 'email' and 'name'")

        email = row["email"]
        name = row["name"]
        if not isinstance(email, str) or not isinstance(name, str):
            raise ValueError(f"row {index} fields 'email' and 'name' must be strings")

        email = email.strip()
        name = name.strip()

        if not email:
            raise ValueError(f"row {index} field 'email' must not be empty")
        if email.count("@") != 1:
            raise ValueError(f"row {index} field 'email' must contain exactly one '@'")
        local_part, _, domain_part = email.partition("@")
        if not local_part or not domain_part:
            raise ValueError(f"row {index} field 'email' must have nonempty local part and domain")
        if any(character.isspace() for character in email):
            raise ValueError(f"row {index} field 'email' must not contain whitespace")
        if not name:
            raise ValueError(f"row {index} field 'name' must not be empty")

        email = email.lower()
        if email in seen:
            raise ValueError(f"row {index} duplicates contact email '{email}' within the batch")
        seen.add(email)
        normalized.append((email, name))
    return normalized

def import_contacts(connection, rows):
    normalized = _validate_batch(rows)
    if not normalized:
        return {"inserted": 0, "updated": 0}

    inserted = 0
    updated = 0
    try:
        if not connection.in_transaction:
            connection.execute("BEGIN")
        stored = {}
        for stored_email, _stored_name in get_contacts(connection):
            key = stored_email.lower()
            if key not in stored:
                stored[key] = stored_email
        for email, name in normalized:
            existing_email = stored.get(email)
            if existing_email is None:
                insert_contact(connection, email, name)
                inserted += 1
            else:
                update_contact_name(connection, existing_email, name)
                updated += 1
        connection.commit()
    except Exception:
        connection.rollback()
        raise
    return {"inserted": inserted, "updated": updated}
